WITH unpacked AS (SELECT id, created_at, ship_to, attributes, EXISTS(items, li -> li.price > 100) AS has_premium_item, ship_to.country AS ship_country, ship_to.city AS ship_city FROM carts WHERE HOUR(created_at) BETWEEN 9 AND 13) SELECT ship_city, COUNT_IF(ship_city = 'Chiang Mai') AS chiang_mai_events, COUNT(*) AS cnt, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min FROM unpacked GROUP BY 1 ORDER BY chiang_mai_events DESC NULLS FIRST
